from .rules import RuleResult

RANK = {"APPROVE": 0, "STEP_UP": 1, "DECLINE": 2}


def ml_decision(score: float, p: dict) -> str:
    if score > p.get("decline_above", 0.92):
        return "DECLINE"
    if score >= p.get("approve_below", 0.70):
        return "STEP_UP"
    return "APPROVE"


def combine(rules: RuleResult, score: float | None, p: dict) -> RuleResult:
    mode = p.get("ml_mode", "shadow")
    if score is None or mode == "off":
        return rules
    ml = ml_decision(score, p)
    rules.score, rules.shadow = round(score, 4), ml
    if mode == "live" and RANK[ml] > RANK[rules.decision]:
        return RuleResult(ml, rules.reasons + [f"ml_{ml.lower()}"], rules.score, ml)
    return rules
